	visible = {
		always = yes
	}

	cooldown = { days = 365 }

	selected = {
		has_variable = epidemic_control_button_var
	}

	ai_chance = {
		value = 10
	}

	possible = {
		has_technology_researched = malaria_prevention
		has_technology_researched = central_planning
        institution_investment_level = {
            institution = institution_health_system
            value >= 2
        }
